const lessons=[{"sentences":[{"speaker":"A","text":"Good morning because I bought a jacket yesterday that is far too large for me.","position":1,"audioStartSeconds":0,"audioEndSeconds":4.811708333333334},{"speaker":"B","text":"Good morning and do not worry since we can easily help you exchange that item.","position":2,"audioStartSeconds":5.011708333333333,"audioEndSeconds":9.797625},{"speaker":"A","text":"That is wonderful news because I was afraid I would lose my money completely.","position":3,"audioStartSeconds":9.997625,"audioEndSeconds":14.869541666666667},{"speaker":"B","text":"Not at all although you must follow our simple packing rules before sending it back.","position":4,"audioStartSeconds":15.069541666666666,"audioEndSeconds":20.160541666666667},{"speaker":"A","text":"What exactly should I do when I prepare the box today?","position":5,"audioStartSeconds":20.360541666666666,"audioEndSeconds":23.981666666666666},{"speaker":"B","text":"First you need to place the jacket inside the original plastic bag very carefully.","position":6,"audioStartSeconds":24.18166666666667,"audioEndSeconds":29.413625},{"speaker":"A","text":"Should I also include the paper receipt inside the package with the clothing?","position":7,"audioStartSeconds":29.613625,"audioEndSeconds":34.08525},{"speaker":"B","text":"Yes because if the receipt is missing our team cannot process your refund quickly.","position":8,"audioStartSeconds":34.28525,"audioEndSeconds":39.32391666666667},{"speaker":"A","text":"Where can I find the official return label that you mentioned earlier?","position":9,"audioStartSeconds":39.523916666666665,"audioEndSeconds":43.66054166666667},{"speaker":"B","text":"You will find that sticky label printed directly on the back of your invoice.","position":10,"audioStartSeconds":43.86054166666667,"audioEndSeconds":48.577},{"speaker":"A","text":"Do I need to pay any extra money at the local post office counter?","position":11,"audioStartSeconds":48.777,"audioEndSeconds":53.106875},{"speaker":"B","text":"No because our company provides free return shipping if you use our partner courier.","position":12,"audioStartSeconds":53.306875,"audioEndSeconds":58.629041666666666},{"speaker":"A","text":"When will the delivery driver come to pick up the parcel from my house?","position":13,"audioStartSeconds":58.82904166666667,"audioEndSeconds":63.03008333333333},{"speaker":"B","text":"He will arrive tomorrow afternoon if you book the collection online this morning.","position":14,"audioStartSeconds":63.23008333333333,"audioEndSeconds":67.98525},{"speaker":"A","text":"Thank you for explaining everything so clearly and patiently to me today.","position":15,"audioStartSeconds":68.18525,"audioEndSeconds":73.05754166666667},{"speaker":"B","text":"You are very welcome and have a wonderful rest of your day.","position":16,"audioStartSeconds":73.25754166666667,"audioEndSeconds":77.18675}],"questions":[{"prompt":"What is the main purpose of the customer's call?","options":["To buy a new winter jacket.","To return an unsuitable item.","To complain about high prices."],"answer":"B","evidenceSentence":1,"evidence":"bought a jacket yesterday that is far too large","explanation":"Khách hàng gọi điện vì mua phải chiếc áo khoác quá rộng và muốn đổi trả."},{"prompt":"What does the customer fear might happen initially?","options":["Losing her money completely.","Paying for expensive shipping.","Waiting too long for delivery."],"answer":"A","evidenceSentence":3,"evidence":"I was afraid I would lose my money completely","explanation":"Khách hàng lo lắng ban đầu rằng cô ấy sẽ bị mất tiền hoàn lại."},{"prompt":"What must be placed inside the package along with the jacket?","options":["A small gift.","The paper receipt.","An identity card."],"answer":"B","evidenceSentence":7,"evidence":"include the paper receipt inside the package","explanation":"Nhân viên nhắc khách hàng cần để biên lai giấy vào trong kiện hàng."},{"prompt":"Where is the return label located?","options":["Sent by separate email.","Printed on the invoice.","Available at the post office."],"answer":"B","evidenceSentence":10,"evidence":"printed directly on the back of your invoice","explanation":"Nhãn đổi trả được in trực tiếp ở mặt sau hóa đơn của khách hàng."},{"prompt":"Why does the customer not need to pay at the post office?","options":["The shop provides free shipping.","The post office is closed today.","She already paid yesterday."],"answer":"A","evidenceSentence":12,"evidence":"company provides free return shipping","explanation":"Công ty cung cấp dịch vụ vận chuyển trả hàng miễn phí nên cô ấy không phải trả tiền."},{"prompt":"What action should the customer take next to arrange collection?","options":["Call the post office tonight.","Book the collection online.","Wait for a random driver."],"answer":"B","evidenceSentence":14,"evidence":"book the collection online this morning","explanation":"Khách hàng cần đặt lịch thu gom trực tuyến vào buổi sáng để tài xế đến vào ngày mai."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
